import math
def run_ucb(rewards, rounds, c):
    k = len(rewards)
    counts = [0] * k
    sums = [0.0] * k
    for t in range(rounds):
        if t < k:
            arg = t
        else:
            total = sum(counts)
            best = -1e18
            arg = 0
            for i in range(k):
                s = sums[i] / counts[i] + c * math.sqrt(2 * math.log(total) / counts[i])
                if s > best + 1e-12:
                    best = s
                    arg = i
        counts[arg] += 1
        sums[arg] += rewards[arg]
    return counts

