def tree_stats(parents):
    # your code
    pass

practice.solution:
def tree_stats(parents):
    n = len(parents)
    depth = [0] * n
    for i in range(n):
        d = 0
        j = i
        while parents[j] != -1:
            j = parents[j]
            d += 1
        depth[i] = d
    has_child = [0] * n
    for i in range(n):
        if parents[i] != -1:
            has_child[parents[i]] = 1
    leaves = n - sum(has_child)
    return [n, max(depth), leaves]

